        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.Equal(N(a50, a20, a10), stockAfter);
        Assert.Equal(Account with { Balance = Account.Balance + N(d50, d20, d10).Value }, result.Account);
    }

